import {h,Component} from 'preact';
import {useEffect,useRef,useState} from 'preact/hooks';
import {api} from './api.js';
import {store} from './store.js';
import {trackRouteHeading} from './route-focus.js';
import {createSessionCheck} from './session-check.js';
import {parseLocation,matchRoute,navigate} from './router.js';
import {navigation} from './nav.js';
import {Login,Signup} from './pages/auth/forms.jsx';
import {routes as people} from './pages/people/routes.jsx';
import {routes as work} from './pages/work/routes.jsx';
import {routes as insight} from './pages/insight/routes.jsx';
import {Page,Notice,Button} from './components/ui.jsx';
import {Overview} from './pages/overview.jsx';
import './styles/shell.css';
const routes=[{path:'/',component:Overview},{path:'/login',component:Login},{path:'/signup',component:Signup},...people,...work,...insight];
function publicRoute(path){return ['/login','/signup','/reset','/invitations/accept'].some(item=>path===item||path.startsWith(item+'/'));}
class RouteBoundary extends Component {
  constructor(props){super(props);this.state={error:null};}
  static getDerivedStateFromError(error){return {error};}
  componentDidUpdate(previous){if(previous.resource!==this.props.resource&&this.state.error)this.setState({error:null});}
  render(){
    if(!this.state.error)return this.props.children;
    return <Page title="This page could not be displayed"><p>Your saved work remains on the server. Reload the page before repeating a change.</p><button onClick={()=>globalThis.location.reload()}>Reload Crew</button><a href="#/">Open overview</a></Page>;
  }
}
export function App() {
  const [location,setLocation]=useState(()=>parseLocation(globalThis.location.hash));
  const [state,setState]=useState(store.get());
  const [startup,setStartup]=useState({loading:true,error:null});
  const [attempt,setAttempt]=useState(0);
  const [logoutState,setLogoutState]=useState({busy:false,error:null});
  const [sessionState,setSessionState]=useState({checking:false,error:null,lastChecked:null});
  const sessionCheck=useRef(null);
  const [online,setOnline]=useState(()=>globalThis.navigator?.onLine!==false);
  const main=useRef(null),logoutOwner=useRef(null);
  useEffect(()=>store.subscribe(setState),[]);
  useEffect(()=>{
    const change=()=>setLocation(parseLocation(globalThis.location.hash));
    const connected=()=>setOnline(globalThis.navigator?.onLine!==false);
    window.addEventListener('hashchange',change);window.addEventListener('online',connected);window.addEventListener('offline',connected);change();
    return()=>{window.removeEventListener('hashchange',change);window.removeEventListener('online',connected);window.removeEventListener('offline',connected);logoutOwner.current?.abort();};
  },[]);
  useEffect(()=>{
    const owner=new AbortController();let active=true;setStartup({loading:true,error:null});
    api.get('/me',{signal:owner.signal}).then(result=>{if(active){store.set({user:result.user});setStartup({loading:false,error:null});}},error=>{
      if(!active)return;
      if(error.status===401){store.set({user:null,organization:null,notice:null});setStartup({loading:false,error:null});}
      else setStartup({loading:false,error});
    });
    return()=>{active=false;owner.abort();};
  },[attempt]);
  useEffect(()=>{
    if(startup.loading||startup.error)return;
    return trackRouteHeading(main.current);
  },[location.pathname,startup.loading,startup.error]);
  useEffect(()=>{
    if(startup.loading||startup.error)return;
    const checker=createSessionCheck({api,store,notify:setSessionState});
    sessionCheck.current=checker;
    return()=>{checker.dispose();if(sessionCheck.current===checker)sessionCheck.current=null;};
  },[startup.loading,startup.error]);
  async function logout(){
    if(logoutOwner.current)return;
    const owner=new AbortController();logoutOwner.current=owner;setLogoutState({busy:true,error:null});
    try{await api.post('/auth/logout',{}, {signal:owner.signal});if(owner.signal.aborted)return;store.set({user:null,organization:null,notice:null});navigate('/login');}
    catch(error){if(!owner.signal.aborted)setLogoutState({busy:false,error});}
    finally{if(logoutOwner.current===owner){logoutOwner.current=null;if(!owner.signal.aborted)setLogoutState(current=>({...current,busy:false}));}}
  }
  if(startup.loading)return <main aria-busy="true" role="status">Opening Crew…</main>;
  if(startup.error)return <main><Page title="Crew could not check your session"><Notice error={startup.error}/><p>Check your connection, then try again. Your saved credentials and draft data have not been replaced.</p><button onClick={()=>setAttempt(value=>value+1)}>Check session again</button></Page></main>;
  const effective=!state.user&&!publicRoute(location.pathname)?'/login':location.pathname;
  let matched=null,params={};
  for(const route of routes){const result=matchRoute(route.path,effective);if(result){matched=route;params=result;break;}}
  const View=matched?.component;
  const returnTo=effective==='/login'&&location.pathname!=='/login'?location.pathname+(Object.keys(location.query).length?'?'+new URLSearchParams(location.query):''):undefined;
  return <div className="app-shell">
    <a href="#crew-content" className="skip-link" onClick={event=>{event.preventDefault();main.current?.focus();}}>Skip to content</a>
    <aside><a className="brand" href="#/">crew<span>team work</span></a>{state.user&&<nav aria-label="Main navigation">{navigation.map(item=><a key={item.path} href={'#'+item.path} aria-current={item.path===location.pathname?'page':undefined}>{item.label}</a>)}</nav>}<footer>{state.user&&<><span>{state.user.name}</span><Button busy={logoutState.busy} onClick={logout}>Sign out</Button><Button busy={sessionState.checking} onClick={()=>sessionCheck.current?.check()}>Check session</Button><span role="status">{sessionState.checking?'Checking session…':sessionState.lastChecked?'Session checked '+new Date(sessionState.lastChecked).toLocaleTimeString():''}</span></>}</footer></aside>
    <main ref={main} id="crew-content" tabIndex={-1}>
      {!online&&<Notice>You appear to be offline. Loaded pages may be out of date; changes still require a server response.</Notice>}
      <Notice error={sessionState.error}/>
      <Notice error={logoutState.error}/><Notice>{state.notice}</Notice>
      <RouteBoundary resource={effective}><div key={effective+':'+(state.user?.id??'anonymous')}>{View?<View params={params} query={location.query} returnTo={returnTo} user={state.user} api={api} store={store} navigate={navigate}/>:<Page title="Page not found"><a href="#/">Return to overview</a></Page>}</div></RouteBoundary>
    </main>
  </div>;
}

export function createSessionCheck({api,store,notify=()=>{},target=globalThis.window,document=globalThis.document,deadline=10000}) {
  let disposed=false;
  let owner=null;
  let state={checking:false,error:null,lastChecked:null};
  function publish(patch) {
    if (disposed) return;
    state={...state,...patch};
    notify(state);
  }
  function owns(record) {
    return !disposed && owner===record && store.get().user===record.user;
  }
  function release(record) {
    clearTimeout(record.timer);
    if (owner===record) owner=null;
  }
  function cancel() {
    if (!owner) return;
    const record=owner;
    release(record);
    record.controller.abort();
    record.cancel();
    publish({checking:false,error:null,lastChecked:null});
  }
  async function perform(record) {
    try {
      const result=await Promise.race([api.get('/me',{signal:record.controller.signal}),record.deadline]);
      if (!owns(record)) return false;
      if (!result?.user?.id) throw new Error('Crew did not return an account. Check your session again.');
      release(record);
      publish({checking:false,error:null,lastChecked:new Date().toISOString()});
      const changed=result.user.id!==record.user.id;
      store.set(changed
        ? {user:result.user,organization:null,notice:'Your signed-in account changed. Review the current page before making changes.'}
        : {user:result.user});
      return true;
    } catch (error) {
      if (!owns(record)) return false;
      release(record);
      if (error.status===401) {
        publish({checking:false,error:null,lastChecked:null});
        store.set({user:null,organization:null,notice:'Your session has ended. Sign in again to return to this page.'});
      } else {
        publish({checking:false,error,lastChecked:state.lastChecked});
      }
      return false;
    }
  }
  function check() {
    if (disposed || !store.get().user) return Promise.resolve(false);
    if (owner) return owner.promise;
    const record={user:store.get().user,controller:new AbortController()};
    record.deadline=new Promise((resolve,reject)=>{
      record.cancel=()=>resolve(null);
      record.timer=setTimeout(()=>{
        const error=new Error('The session check timed out. Check your connection, then try again.');
        error.code='SESSION_CHECK_TIMEOUT';
        reject(error);
        record.controller.abort();
      },deadline);
    });
    owner=record;
    publish({checking:true,error:null});
    record.promise=perform(record);
    return record.promise;
  }
  function returned() {
    if (document?.visibilityState!=='hidden') void check();
  }
  function restored(event) {
    if (event.persisted) returned();
  }
  const unsubscribe=store.subscribe(()=>{
    if (owner && store.get().user!==owner.user) cancel();
  });
  target?.addEventListener('focus',returned);
  target?.addEventListener('pageshow',restored);
  document?.addEventListener('visibilitychange',returned);
  return {
    check,
    get:()=>state,
    dispose() {
      if (disposed) return;
      disposed=true;
      cancel();
      unsubscribe();
      target?.removeEventListener('focus',returned);
      target?.removeEventListener('pageshow',restored);
      document?.removeEventListener('visibilitychange',returned);
    }
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {createSessionCheck} from '../src/session-check.js';
import {createStore} from '../src/store.js';
function fixture(options={}) {
  const target=new EventTarget(),document=new EventTarget();document.visibilityState='visible';
  const user={id:'one',name:'Original account'};
  const store=createStore({user,organization:{id:'org'},notice:null});
  const calls=[],states=[];
  const api={get(path,request){return new Promise((resolve,reject)=>calls.push({path,request,resolve,reject}));}};
  const checker=createSessionCheck({api,store,target,document,notify:value=>states.push(value),...options});
  return {checker,target,document,store,user,calls,states};
}
test('session checks coalesce simultaneous manual and visible tab-return requests',async()=>{
  const f=fixture();try{
    const first=f.checker.check();f.target.dispatchEvent(new Event('focus'));f.document.dispatchEvent(new Event('visibilitychange'));
    assert.equal(f.checker.check(),first);assert.equal(f.calls.length,1);assert.equal(f.calls[0].path,'/me');
    f.calls[0].resolve({user:{id:'one',name:'Current account'}});assert.equal(await first,true);
    assert.equal(f.store.get().user.name,'Current account');assert.equal(f.store.get().organization.id,'org');
    assert.equal(f.checker.get().checking,false);assert.match(f.checker.get().lastChecked,/Z$/);
  }finally{f.checker.dispose();}
});
test('confirmed session expiry clears authenticated identity and organization while retaining a sign-in explanation',async()=>{
  const f=fixture();try{
    const result=f.checker.check();f.calls[0].reject(Object.assign(new Error('Please sign in'),{status:401}));
    assert.equal(await result,false);assert.equal(f.store.get().user,null);assert.equal(f.store.get().organization,null);
    assert.match(f.store.get().notice,/session has ended/);assert.equal(f.checker.get().error,null);
  }finally{f.checker.dispose();}
});
test('a connection failure preserves the account and a deliberate later check can recover',async()=>{
  const f=fixture();try{
    const first=f.checker.check();const error=new Error('Connection unavailable');f.calls[0].reject(error);
    assert.equal(await first,false);assert.equal(f.store.get().user,f.user);assert.equal(f.checker.get().error,error);assert.equal(f.calls.length,1);
    const second=f.checker.check();f.calls[1].resolve({user:f.user});assert.equal(await second,true);assert.equal(f.checker.get().error,null);
  }finally{f.checker.dispose();}
});
test('an old session response cannot replace a newer authenticated account even when transport ignores abort',async()=>{
  const f=fixture();try{
    const old=f.checker.check(),next={id:'two',name:'New account'};f.store.set({user:next});
    assert.equal(f.calls[0].request.signal.aborted,true);assert.equal(await old,false);
    f.calls[0].resolve({user:f.user});await new Promise(resolve=>setImmediate(resolve));
    assert.equal(f.store.get().user,next);assert.equal(f.checker.get().checking,false);
  }finally{f.checker.dispose();}
});
test('disposing a pending session check drains its ownership and removes tab listeners',async()=>{
  const f=fixture();const pending=f.checker.check();const before=f.states.length;f.checker.dispose();f.checker.dispose();
  assert.equal(await pending,false);assert.equal(f.calls[0].request.signal.aborted,true);
  f.calls[0].reject(Object.assign(new Error('late expiry'),{status:401}));f.target.dispatchEvent(new Event('focus'));
  await new Promise(resolve=>setImmediate(resolve));assert.equal(f.calls.length,1);assert.equal(f.store.get().user,f.user);assert.equal(f.states.length,before);
});
test('session check deadlines settle ignored transports without clearing a valid account',async()=>{
  const f=fixture({deadline:5});try{
    assert.equal(await f.checker.check(),false);assert.equal(f.calls[0].request.signal.aborted,true);
    assert.equal(f.checker.get().error.code,'SESSION_CHECK_TIMEOUT');assert.equal(f.store.get().user,f.user);
    f.calls[0].resolve({user:{id:'late'}});await new Promise(resolve=>setImmediate(resolve));assert.equal(f.store.get().user,f.user);
  }finally{f.checker.dispose();}
});
test('unreadable successful session responses retain current identity and expose a check error',async()=>{
  const f=fixture();try{
    const pending=f.checker.check();f.calls[0].resolve({user:null});assert.equal(await pending,false);
    assert.equal(f.store.get().user,f.user);assert.match(f.checker.get().error.message,/did not return an account/);
  }finally{f.checker.dispose();}
});
test('a confirmed different server account resets the previous organization context',async()=>{
  const f=fixture();try{
    const pending=f.checker.check();f.calls[0].resolve({user:{id:'two',name:'Other account'}});assert.equal(await pending,true);
    assert.equal(f.store.get().user.id,'two');assert.equal(f.store.get().organization,null);assert.match(f.store.get().notice,/account changed/);
  }finally{f.checker.dispose();}
});
test('hidden tabs and anonymous pages do not start session checks, while persisted visible restoration does',async()=>{
  const f=fixture();try{
    f.document.visibilityState='hidden';f.target.dispatchEvent(new Event('focus'));f.document.dispatchEvent(new Event('visibilitychange'));assert.equal(f.calls.length,0);
    f.document.visibilityState='visible';f.target.dispatchEvent(new Event('pageshow'));assert.equal(f.calls.length,0);
    const event=new Event('pageshow');Object.defineProperty(event,'persisted',{value:true});f.target.dispatchEvent(event);assert.equal(f.calls.length,1);
    f.store.set({user:null});assert.equal(await f.checker.check(),false);assert.equal(f.calls[0].request.signal.aborted,true);
    f.target.dispatchEvent(new Event('focus'));assert.equal(f.calls.length,1);
  }finally{f.checker.dispose();}
});
